import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Fotoğraflar bazen yan durur. Telefon dik tutulurken çekilen fotoğraf, bilgisayarda yatay görünür.</p>\n<p>Döndürme ve çevirme, bu sorunu çözen en basit düzenlemelerdir. Birkaç tıklamayla fotoğraf doğru yöne gelir.</p>\n<p>Bu kılavuz, döndürme ve çevirmenin ne yaptığını, açıların nasıl seçildiğini ve EXIF yönlendirmesinin neden fotoğrafları yan gösterdiğini anlatıyor.</p>\n<h2 id=\"what-rotation-and-flipping-do\">Döndürme ve çevirme gerçekte ne yapar?</h2>\n<p>Döndürme, görseli saat yönünde ya da tersine çevirir. 90 derece döndürülen bir fotoğraf, yan durmaktan dik durmaya geçer.</p>\n<p>Çevirme ise görseli aynalar. Yatay çevirme, sol ile sağı değiştirir; dikey çevirme, üst ile altı değiştirir.</p>\n<p>İki işlem farklıdır. Döndürme yönü değiştirir; çevirme görüntüyü aynalar.</p>\n<h2 id=\"why-photos-end-up-sideways\">Fotoğraflar neden yan çıkar?</h2>\n<p>Telefonlar, çekim yönünü EXIF verisine yazar. Bazı programlar bu veriyi okumaz ve fotoğrafı yan gösterir.</p>\n<p>Telefon galerisi EXIF'i okur; web sitesi okumayabilir. Aynı fotoğraf telefonda doğru, sitede yan görünür.</p>\n<p>Eski kameralar da yönü kaydetmez. Fotoğraf, çekildiği yönde kalır; sonradan düzeltmek gerekir.</p>\n<h2 id=\"rotation-angles-explained\">Döndürme açıları: 90, 180 ve özel açılar</h2>\n<p>90 derece, yan duran fotoğrafı düzeltir. Bir kez 90 derece döndürmek genellikle yeterlidir.</p>\n<p>180 derece, baş aşağı duran fotoğrafı düzeltir. İki kez 90 derece döndürmekle aynıdır.</p>\n<p>Özel açılar, hafif eğik fotoğrafları düzeltir. Ufuk çizgisi eğikse 2-3 derecelik döndürme yeterlidir.</p>\n<h2 id=\"flip-horizontal-vs-vertical\">Yatay çevirme ve dikey çevirme</h2>\n<p>Yatay çevirme, aynadaki görüntüyü verir. Ön kamerayla çekilen selfieler genellikle aynalıdır; yatay çevirme düzeltir.</p>\n<p>Dikey çevirme, üst ile altı değiştirir. Baş aşağı çekilen fotoğraflarda kullanılır ama nadirdir.</p>\n<p>Hangi çevirmenin gerektiğini anlamak için yazıya bakın. Yazı ters okunuyorsa yatay çevirme gerekir.</p>\n<h2 id=\"exif-orientation-basics\">EXIF yönlendirmesi: bazı fotoğraflar neden kendiliğinden döner?</h2>\n<p>Telefonlar, pikselleri döndürmek yerine yönü EXIF verisine yazar. Bu, hızlıdır ama her program veriyi okumaz.</p>\n<p>EXIF'i okuyan program fotoğrafı doğru gösterir; okumayan yan gösterir. Sorun, programların farklı davranmasıdır.</p>\n<p>Kalıcı çözüm, pikselleri gerçekten döndürmektir. Döndürülen fotoğraf her programda doğru görünür.</p>\n<h2 id=\"formats-and-quality\">Formatlar ve kalite: dosyanıza ne olur?</h2>\n<p>90 derecelik döndürme kayıpsızdır. JPG bile 90 derece döndürmede kalite kaybetmez.</p>\n<p>Özel açılar kalite kaybettirir. Eğik döndürme, pikselleri yeniden örnekler ve hafif bulanıklık yapar.</p>\n<p>PNG döndürme her zaman kayıpsızdır. Kayıpsız format, her açıda kaliteyi korur.</p>\n<h2 id=\"batch-rotation\">Birçok fotoğrafı aynı anda döndürmek</h2>\n<p>Tatilde çekilen onlarca fotoğraf aynı yönde yan olabilir. Tümünü aynı anda yükleyip toplu döndürün.</p>\n<p>Toplu döndürmede tüm fotoğraflar için aynı açıyı kullanın. Hepsi aynı yönde çekildiyse tek işlem yeterlidir.</p>\n<p>Farklı yönlerdeki fotoğrafları ayırın. Karışık yönler, toplu işlemde hata çıkarır.</p>\n<h2 id=\"straightening-tilted-photos\">Eğik fotoğrafı köşeleri kaybetmeden düzeltmek</h2>\n<p>Eğik fotoğrafı düzeltirken köşeler kırpılır. Döndürme, köşeleri dışarı taşır; kırpma gerekir.</p>\n<p>Küçük açılar az kırpar. 2-3 derecelik düzeltmede kayıp önemsizdir.</p>\n<p>Büyük açılar çok kırpar. 10 derecenin üzerinde düzeltme, fotoğrafın önemli kısmını kesebilir.</p>\n<h2 id=\"fixing-mirrored-selfies\">Aynalı selfieyi düzeltmek</h2>\n<p>Ön kameralar aynalı çeker. Selfie, size doğru görünür ama başkalarına ters görünür.</p>\n<p>Yatay çevirme, aynayı düzeltir. Yazılar doğru okunur ve yüz simetrisi gerçeğe döner.</p>\n<p>Telefon ayarlarından aynalı çekimi kapatabilirsiniz. Böylece selfieler baştan doğru çıkar.</p>\n<h2 id=\"rotate-vs-crop\">Döndürmek mi kırpmak mı: önce hangisi?</h2>\n<p>Önce döndürün, sonra kırpın. Döndürme, kırpma alanını değiştirir; sıralama önemlidir.</p>\n<p>Kırpma, döndürmeden sonra yapılmalıdır. Döndürülen fotoğrafın köşeleri kırpılır; kırpma bunu düzeltir.</p>\n<p>İki işlemi aynı araçta yapmak pratiktir. Önce yönü düzeltin, sonra çerçeveyi ayarlayın.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: fotoğraflarınız cihazınızda kalır</h2>\n<p>Döndürme aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu, özel fotoğraflar için önemlidir. Kimlik ve aile fotoğraflarını güvenle düzenleyebilirsiniz.</p>\n<p>İş bitince tarayıcı verisi silinir. Fotoğraflarınız cihazınızdan ayrılmaz.</p>\n<h2 id=\"common-mistakes\">Görsel döndürürken yaygın hatalar</h2>\n<p>En yaygın hata, EXIF'i düzeltmeden döndürmektir. EXIF yönü kalırsa fotoğraf bazı programlarda yine yan görünür.</p>\n<p>Bir başka hata, orijinali silmektir. Döndürülen fotoğraf ayrı bir dosyadır; orijinali saklayın.</p>\n<p>Üçüncü hata, yanlış yönde döndürmektir. Önizlemeyi kontrol etmeden indirmeyin.</p>\n<h2 id=\"when-to-rotate-vs-reshoot\">Ne zaman döndürmeli, ne zaman yeniden çekmeli?</h2>\n<p>Fotoğraf yan duruyorsa döndürün. Yön sorunu, düzenlemeyle çözülür.</p>\n<p>Fotoğraf bulanıksa yeniden çekin. Döndürme, bulanıklığı düzeltmez.</p>\n<p>Işık kötüyse yeniden çekin. Düzenleme, kötü ışığı kurtaramaz.</p>\n<h2 id=\"rotating-scanned-receipts\">Taranan fiş ve formları döndürmek</h2>\n<p>Taramalar genellikle yan çıkar. Fişi okumak için 90 derece döndürmek gerekir.</p>\n<p>Taranan belgeleri döndürdükten sonra kontrol edin. Yazılar doğru yönde okunmalıdır.</p>\n<p>Belgeleri döndürüp PDF'ye çevirin. PDF, belgelerin paylaşım formatıdır.</p>\n<h2 id=\"rotation-and-printing\">Baskı için görsel döndürmek</h2>\n<p>Baskıdan önce yönü kontrol edin. Yan basılan fotoğraf, kâğıdı boşa harcar.</p>\n<p>Baskı merkezine göndermeden önce fotoğrafı açın. Yön doğru olmalıdır.</p>\n<p>Dikey fotoğrafları dikey kâğıda basın. Yanlış yön, fotoğrafı kırpar.</p>\n<h2 id=\"rotation-file-naming\">Döndürülen dosyaları adlandırma ve düzenleme</h2>\n<p>Döndürülen dosyalara anlaşılır ad verin. Orijinal adın sonuna yön bilgisi ekleyin.</p>\n<p>Orijinalleri ayrı klasörde tutun. Döndürülenler ve orijinaller karışmamalıdır.</p>\n<p>Toplu döndürmede adlar korunur. Yalnızca uzantı aynı kalır; düzen bozulmaz.</p>\n<h2 id=\"combining-rotation-with-edits\">Döndürmeyi diğer düzenlemelerle birleştirmek</h2>\n<p>Döndürme, kırpma ve boyutlandırma bir arada yapılabilir. Önce döndürün, sonra kırpın, sonra boyutlandırın.</p>\n<p>Sıralama önemlidir. Yanlış sıra, gereksiz kırpmaya yol açar.</p>\n<p>Tüm düzenlemeleri bitirdikten sonra indirin. Ara adımlarda indirmek, kalite kaybettirir.</p>\n<p>Özetle: önce yönü düzeltin, sonra diğer düzenlemelere geçin. Adımlar için <a href=\"/tr/blog/gorsel-nasil-dondurulur-cevrilir\">Görsel döndürme ve çevirme nasıl yapılır</a> yazısına bakın; EXIF sorunları için <a href=\"/tr/blog/gorsel-yonlendirme-exif-dondurme\">EXIF yönlendirme sorunları</a> yazısı yardımcı olur. Kırpma için <a href=\"/tr/gorsel-kirp\">görsel kırpıcı</a>, boyut için <a href=\"/tr/gorsel-boyutlandir\">görsel boyutlandırıcı</a> hazırdır; araç ise <a href=\"/tr/gorsel-dondur-cevir\">görsel döndürme ve çevirme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Görsel döndürmek mi yoksa çevirmek mi daha uygun?","answer":"Yön yanlışsa döndürün; görüntü aynalıysa çevirin. Yan duran fotoğraf 90 derece döndürmeyle düzelir. Ön kamerayla çekilen aynalı selfie ise yatay çevirmeyle düzelir. Yazı ters okunuyorsa çevirme gerekir."},{"question":"Fotoğrafımı döndürmek dosyanın çok büyümesine yol açar mı?","answer":"Hayır. 90 derecelik döndürme dosya boyutunu değiştirmez; yalnızca piksellerin yönünü değiştirir. Özel açılar hafif büyüme yapabilir ama fark önemsizdir. Döndürme, dosyayı büyütmez."},{"question":"Fotoğrafım galerimde doğru görünüyor ama web sitesinde neden yan görünüyor?","answer":"Çünkü telefon galerisi EXIF yönlendirmesini okur, web sitesi okumayabilir. Telefon, yönü EXIF verisine yazar; site bu veriyi yok sayarsa fotoğraf yan görünür. Kalıcı çözüm, pikselleri gerçekten döndürmektir."},{"question":"Hem yan hem baş aşağı duran taranmış bir belgeyi döndürebilir miyim?","answer":"Evet. Önce 180 derece döndürün, sonra 90 derece döndürün; ya da doğru açıyı tek seferde seçin. Önizlemede yazıların doğru yönde okunduğunu kontrol edin."},{"question":"Hafif eğik bir ufku düzeltmek için hangi açıyı kullanmalıyım?","answer":"Genellikle 2-3 derece yeterlidir. Önizlemede ufuk çizgisini izleyin; çizgi yatay olunca durun. Küçük açılar az kırpar; büyük açılar fotoğrafın köşelerini keser."},{"question":"Görsel döndürmek konum verilerini siler mi?","answer":"Hayır, döndürme EXIF verilerini silmez; konum bilgisi korunur. Konumu silmek istiyorsanız meta veri kaldırma aracını kullanın. Gizlilik için paylaşmadan önce konum verisini kontrol edin."}];
